import {createAgentStudio,createEventViewer,renderAgentDocs} from './agent-studio.js';
import {DIMENSIONS,STATUS,assessment,history,parseRoute,route,validateRun} from './core.js';
import {createGardenScene} from './garden-scene.js';
import {createStudio,renderDocs,saveFile,evidenceLinks} from './studio.js';
import {markdownReport,validateSpecification} from './specification.js';

const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon={arrow:'<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>',play:'<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m9 5 11 7-11 7z"/></svg>',leaf:'<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M19 4C9 2 3 7 5 14c2 7 13 8 14-10ZM5 20 15 9"/></svg>'};
let index,run,scene,studio,eventViewer,playTimer=null,renderToken=0,state=parseRoute(location.hash),inspecting=false,toastTimer;
const cache=new Map();
const storage={read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}},write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Browser storage unavailable. Export to keep your changes.');return false}}};
let criteria=storage.read('deeproject-v2-criteria',{}),reviews=storage.read('deeproject-v2-reviews',{}),imported=storage.read('deeproject-v2-imports',[]);
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
const scenario=()=>index.scenarios.find(s=>s.id===run.scenario);
const currentTurn=()=>run.turns[state.turn-1];
const criterionKey=(dim=state.dimension)=>run.scenario+':'+dim;
const override=(dim=state.dimension)=>criteria[criterionKey(dim)];
const reviewKey=(i=state.turn-1,dim=state.dimension)=>[run.id,i+1,dim,override(dim)?.version||run.rubric_version].join(':');
const options=(i,dim)=>({override:!!override(dim),review:reviews[reviewKey(i,dim)]});
const result=(dim=state.dimension,i=state.turn-1)=>assessment(run,i,dim,options(i,dim));
const past=(dim=state.dimension)=>history(run,state.turn-1,dim,i=>options(i,dim));
const dimName=()=>DIMENSIONS.find(d=>d.id===state.dimension).name;
function originalCriterion(){return run.rubric.split('\n')[0].split(/criterion:\s*/i).pop()}
function criterion(dim=state.dimension){return override(dim)?.text||run.specification?.criteria.filter(c=>c.dimension===dim).map(c=>c.definition).join(' · ')||(dim===run.dimension?originalCriterion():'No criterion has been assessed for this dimension. Add one in Customize.');}
function stop(){clearInterval(playTimer);playTimer=null;const b=$('#play');if(b){b.innerHTML=icon.play+'<span>Play</span>';b.setAttribute('aria-label','Play trajectory')}}
function navigate(page){location.hash=route(page,state.run,state.turn,state.dimension)}
function syncUrl(){historyAPI.replaceState(null,'',route(state.page,state.run,state.turn,state.dimension));syncNav()}
const historyAPI=window.history;
function syncNav(){
 const current=['diagnostics','compare'].includes(state.page)?'workbench':state.page==='run'?'design':state.page;
 document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===current;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');a.href=['design','docs'].includes(a.dataset.nav)?'#'+a.dataset.nav:route(a.dataset.nav,state.run,state.turn,state.dimension)});
}
function closeNavigation(){const drawer=$('#navigation-drawer');if(drawer.open)drawer.close();$('#menu-toggle').setAttribute('aria-expanded','false');document.body.classList.remove('navigation-open');}
function openNavigation(){if(state.page==='home')return;syncNav();$('#navigation-drawer').showModal();$('#menu-toggle').setAttribute('aria-expanded','true');document.body.classList.add('navigation-open');}
$('#menu-toggle').addEventListener('click',openNavigation);
$('#close-navigation').addEventListener('click',closeNavigation);
$('#navigation-drawer').addEventListener('close',()=>{$('#menu-toggle').setAttribute('aria-expanded','false');document.body.classList.remove('navigation-open');});
$('#navigation-drawer').addEventListener('click',e=>{
 if(e.target.closest('a[href]')){closeNavigation();return;}
 if(e.target===$('#navigation-drawer')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeNavigation();}
});


function badge(r){return '<span class="status-pill '+r.status+'"><i></i>'+esc(STATUS[r.status].label)+'</span>'}
function coverage(entry){return entry.kind==='authored'?'Authored illustration':entry.human_count?'Human + LLM records':'LLM records · unreviewed'}
function modelShort(){if(run.kind==='authored')return 'No model run';return run.model_id.split('/').pop()}
function responseExcerpt(t){return t.assistant.slice(0,350)+(t.assistant.length>350?'…':'')}

function renderText(text){
  const lines=String(text||'').split('\n');let html='',code=false,codeLines=[];
  const inline=s=>esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');
  for(let i=0;i<lines.length;i++){
    let line=lines[i];if(line.startsWith('```')){if(code){html+='<pre>'+esc(codeLines.join('\n'))+'</pre>';codeLines=[]}code=!code;continue}if(code){codeLines.push(line);continue}
    if(line.trim().startsWith('|')){let table=[];while(i<lines.length&&lines[i].trim().startsWith('|')){table.push(lines[i].trim().replace(/^\||\|$/g,'').split('|').map(s=>s.trim()));i++}i--;html+='<div class="response-table"><table>'+table.filter(row=>!row.every(c=>/^:?-+:?$/.test(c))).map((row,j)=>'<tr>'+row.map(c=>'<'+(j===0?'th':'td')+'>'+inline(c)+'</'+(j===0?'th':'td')+'>').join('')+'</tr>').join('')+'</table></div>';continue}
    if(/^#{1,6}\s/.test(line)){html+='<h3>'+inline(line.replace(/^#+\s/,''))+'</h3>';continue}
    if(/^[-*_]{3,}\s*$/.test(line)){html+='<hr>';continue}if(!line.trim())continue;
    html+='<p'+(/^[-*]\s/.test(line)?' class="response-bullet"':'')+'>'+inline(line)+'</p>';
  }if(codeLines.length)html+='<pre>'+esc(codeLines.join('\n'))+'</pre>';return html;
}
function caseSelectors(){return '<div class="case-selectors"><label><span class="sr-only">Scenario</span><select id="scenario-select" aria-label="Scenario">'+index.scenarios.map(s=>'<option value="'+esc(s.id)+'" '+(s.id===run.scenario?'selected':'')+'>'+esc(s.name)+'</option>').join('')+'</select></label><span class="selector-divider"></span><label><span class="sr-only">Model</span><select id="model-select" aria-label="Model" '+(run.kind==='authored'?'disabled':'')+'>'+index.runs.filter(r=>r.scenario===run.scenario).map(r=>'<option value="'+esc(r.id)+'" '+(r.id===run.id?'selected':'')+'>'+esc(r.model_label)+'</option>').join('')+'</select></label><button class="icon-button" data-action="metadata" aria-label="View model and run details">ⓘ</button></div>'}
function contextMarkup(){const s=scenario();return '<details class="context-details"><summary>About this case <span>Background &amp; requirements</span></summary><div class="context-body"><p>'+esc(s.description)+'</p><p class="context-goal">'+esc(s.goal)+'</p><div class="constraints">'+(s.constraints||[]).map(c=>'<span>'+esc(c)+'</span>').join('')+'</div>'+(run.kind==='authored'?'<p class="small-note">Author-constructed illustration. No model was run for this example.</p>':'')+'</div></details>'}
function playback(){return '<div class="playback"><button class="button primary play-button" id="play" aria-label="Play trajectory">'+icon.play+'<span>Play</span></button><button class="icon-button step" data-action="prev" aria-label="Previous turn">‹</button><label class="scrubber"><span class="sr-only">Interaction turn</span><input type="range" id="timeline" aria-label="Interaction turn" min="1" max="'+run.turns.length+'" value="'+state.turn+'"></label><button class="icon-button step" data-action="next" aria-label="Next turn">›</button><output id="position">'+state.turn+' <span>/ '+run.turns.length+'</span></output><button class="icon-button" data-action="restart" aria-label="Restart from first turn">↺</button></div>'}
function markers(){return DIMENSIONS.map(d=>'<button class="dim-marker" data-dim="'+d.id+'" aria-label="Inspect '+d.name+'"><span class="marker-letter">'+d.id+'</span><span><strong>'+d.name+'</strong><small class="marker-state">Not assessed</small></span><span class="marker-indicator"></span></button>').join('')}
function sceneMarkup(home=false){
 if(home)return '<div class="garden-stage home-stage"><canvas id="garden-canvas" role="img" aria-label="3D preview of the recorded Aircraft Design example. Enter the garden to inspect its assessments."></canvas><div id="markers" hidden></div></div>';
 return '<div class="garden-stage"><canvas id="garden-canvas" aria-hidden="true"></canvas><div class="dimension-markers" id="markers">'+markers()+'</div><div class="scene-tools"><button class="quiet-button" data-action="overview">Overview ↗</button><span></span><button class="icon-button" data-action="rotate-left" aria-label="Rotate garden left">↶</button><button class="icon-button" data-action="rotate-right" aria-label="Rotate garden right">↷</button><button class="icon-button" data-action="zoom-in" aria-label="Zoom in">+</button><button class="icon-button" data-action="zoom-out" aria-label="Zoom out">−</button></div><div class="scene-hint"><span class="hint-dot"></span><span id="renderer-note">Drag to orbit · scroll to zoom</span></div></div>';
}

function initializeScene(home=false){const el=$('#garden-canvas');if(!el)return;scene=createGardenScene(el,$('#markers'),()=>({statuses:DIMENSIONS.map(d=>result(d.id).status),turn:state.turn,priorIssue:past('A').hasPriorIssue,corrected:run.kind==='authored'&&state.turn===4&&!override('A')}),i=>selectDimension(DIMENSIONS[i].id),{preview:home});if(!home){$('#renderer-note').textContent='3D view · drag to orbit';}paintMarkers();}
function renderHome(){
 $('#main').innerHTML='<section class="hero"><div class="hero-copy"><h1>From opaque AI<br><em>to traceable behavior.</em></h1><div class="hero-actions"><a class="button primary" href="'+route('garden','R06',1,'A')+'" data-enter-garden>Enter the garden '+icon.arrow+'</a><a class="text-link" href="#design">Design an evaluation <span>↗</span></a></div></div><div class="hero-garden">'+sceneMarkup(true)+'</div></section>';initializeScene(true);
}

function finishGardenEntry(stage=$('.garden-stage')){if(!stage)return;stage.querySelector('.garden-entry')?.remove();stage.classList.remove('entering');stage.querySelectorAll('.dimension-markers,.scene-tools').forEach(el=>el.inert=false);}
function renderGarden(fromHome=false){
  $('#main').innerHTML='<section class="workspace-heading"><div><span class="eyebrow">OBSERVE THE TRAJECTORY</span><h1>Behavior, over time.</h1></div></section><section class="garden-workspace"><div class="workspace-toolbar">'+caseSelectors()+'<a class="quiet-button" href="#design">Design standards ↗</a></div>'+contextMarkup()+'<div class="garden-layout" id="garden-layout">'+sceneMarkup()+'<aside class="evidence-panel" id="evidence-panel" hidden aria-label="Selected criterion evidence"></aside></div><div class="garden-bottom"><div class="turn-context"><span class="eyebrow" id="turn-label"></span><p id="turn-request"></p></div>'+playback()+'<div class="assessment-footer"><span id="assessment-source"></span><button class="quiet-button" id="disagreement-link" data-action="assessments" hidden>Assessment difference <span>↗</span></button></div></div></section><div class="garden-under"><span>Plantings group criteria by dimension. Open one to inspect its evidence.</span><span>Only applicable, configured or imported dimensions have ratings.</span></div>';
  initializeScene();paintGarden();let played=false;try{played=sessionStorage.getItem('deeproject-garden-entered')==='yes';sessionStorage.setItem('deeproject-garden-entered','yes')}catch{}if((fromHome||!played)&&!matchMedia('(prefers-reduced-motion: reduce)').matches){scene.enter();const gate=document.createElement('div');gate.className='garden-entry';gate.innerHTML='<button class="quiet-button" data-action="skip-entry">Skip →</button>';const stage=$('.garden-stage');stage.classList.add('entering');stage.querySelectorAll('.dimension-markers,.scene-tools').forEach(el=>el.inert=true);stage.append(gate);setTimeout(()=>finishGardenEntry(stage),2400);}
}
function paintMarkers(){DIMENSIONS.forEach(d=>{let b=$('[data-dim="'+d.id+'"]');if(!b)return;let r=result(d.id);b.className='dim-marker '+r.status+(d.id===state.dimension?' selected':'');b.querySelector('.marker-state').textContent=STATUS[r.status].label;b.setAttribute('aria-pressed',String(inspecting&&d.id===state.dimension));});}
function paintGarden(){
  paintMarkers();const t=currentTurn(),r=result();$('#turn-label').textContent='TURN '+String(state.turn).padStart(2,'0')+' · USER REQUEST';$('#turn-request').textContent=t.user;$('#position').innerHTML=state.turn+' <span>/ '+run.turns.length+'</span>';$('#timeline').value=state.turn;
  $('#assessment-source').innerHTML='<i class="source-dot '+r.status+'"></i>'+esc(r.source);$('#disagreement-link').hidden=!r.disagreement;
  $('#garden-layout').classList.toggle('inspecting',inspecting);$('#evidence-panel').hidden=!inspecting;if(inspecting)paintEvidence();
  document.querySelectorAll('[data-action="prev"]').forEach(b=>b.disabled=state.turn===1);document.querySelectorAll('[data-action="next"]').forEach(b=>b.disabled=state.turn===run.turns.length);
}
function paintEvidence(){const r=result(),h=past(),t=currentTurn();$('#evidence-panel').innerHTML='<div class="panel-top"><span class="eyebrow">'+esc(state.dimension)+' · TURN '+state.turn+'</span><button class="icon-button" data-action="close-evidence" aria-label="Close evidence panel">×</button></div><h2>'+esc(dimName())+'</h2>'+badge(r)+'<p class="source-line">'+esc(r.source)+'</p><div class="criterion-box"><span class="eyebrow">CRITERION</span><p>'+esc(criterion())+'</p></div>'+(h.hasPriorIssue?'<div class="history-note">Earlier issue retained in the history.</div>':'')+'<div class="response-excerpt"><span class="eyebrow">RESPONSE EXCERPT</span><p>'+esc(responseExcerpt(t))+'</p></div><div class="mini-history" aria-label="Criterion history">'+run.turns.map((_,i)=>'<button data-turn="'+(i+1)+'" class="history-node '+(i<state.turn?result(state.dimension,i).status:'future')+(i===state.turn-1?' current':'')+'" '+(i>=state.turn?'disabled':'')+' aria-label="Turn '+(i+1)+(i<state.turn?', '+STATUS[result(state.dimension,i).status].label:', not played yet')+'">'+(i+1)+'</button>').join('')+'</div><a class="button secondary full" href="'+route('diagnostics',run.id,state.turn,state.dimension)+'">View evidence '+icon.arrow+'</a>';}
function selectDimension(dim){if(state.page==='home'){location.hash=route('garden','R06',1,dim);return}stop();state.dimension=dim;inspecting=true;syncUrl();if(state.page==='garden'){paintGarden();scene?.focus(DIMENSIONS.findIndex(d=>d.id===dim));}else renderDiagnostic();}
function setTurn(n){state.turn=Math.max(1,Math.min(run.turns.length,n));syncUrl();if(state.page==='garden')paintGarden();else renderDiagnostic();}
function togglePlay(){if(playTimer){stop();return}if(state.turn===run.turns.length)setTurn(1);$('#play').innerHTML='<span class="pause-icon">Ⅱ</span><span>Pause</span>';$('#play').setAttribute('aria-label','Pause trajectory');playTimer=setInterval(()=>{if(state.turn>=run.turns.length){stop();return}setTurn(state.turn+1)},3200);}
function renderCaseLibrary(){
  const active=run.scenario;$('#main').innerHTML='<section class="workspace-heading"><div><span class="eyebrow">THE EVIDENCE WORKBENCH</span><h1>Start with a conversation.</h1><p>Choose a case. Inspect its judgments and the evidence behind them.</p></div><button class="button secondary" data-action="import">Import case <span>+</span></button></section><div class="case-tabs" role="group" aria-label="Filter cases by scenario">'+index.scenarios.map(s=>'<button data-filter="'+esc(s.id)+'" class="'+(s.id===active?'active':'')+'" aria-pressed="'+(s.id===active)+'">'+esc(s.name)+'</button>').join('')+'</div><section class="case-library"><div class="library-heading"><div><span class="eyebrow">'+esc(scenario().eyebrow||'IMPORTED')+'</span><h2>'+esc(scenario().name)+'</h2><p>'+esc(scenario().description)+'</p></div><span class="small-note">'+index.runs.filter(r=>r.scenario===active).length+' '+(active==='responsible'?'illustration':'recorded runs')+'</span></div><div class="case-rows">'+index.runs.filter(r=>r.scenario===active).map(r=>'<article class="case-row"><div class="model-monogram '+(r.family||'demo')+'">'+esc(r.family==='claude'?'C':r.family==='gemini'?'G':r.family==='gpt'?'O':'D')+'</div><div class="case-name"><h3>'+esc(r.model_label)+'</h3><p>'+esc(r.model_id?.split('/').pop()||'Author-constructed · no model run')+'</p></div><div class="case-row-meta"><span>'+r.turn_count+' turns</span><small>'+esc(coverage(r))+'</small></div><a class="button secondary" href="'+route('diagnostics',r.id,r.id===run.id?state.turn:1,'A')+'">Open case '+icon.arrow+'</a><a class="icon-button" href="'+route('garden',r.id,1,'A')+'" aria-label="View '+esc(r.model_label)+' in garden">'+icon.leaf+'</a></article>').join('')+'</div></section><div class="workbench-note"><span class="note-mark">ⓘ</span><p>Scores apply to the stated criterion. Human and LLM judgments stay separate; agreement is not a guarantee of correctness.</p></div>';
}
function renderWorkbench(){studio.results(run);}
function renderDiagnostic(){
  const t=currentTurn(),r=result();$('#main').innerHTML=studio.tabs('workbench')+'<section class="workspace-heading diagnostic-heading"><div><a class="back-link" href="'+route('workbench',run.id,state.turn,state.dimension)+'">← Results</a><h1>'+esc(scenario().name)+'</h1><p>'+esc(run.model_label)+' <span class="muted">/</span> '+esc(modelShort())+'</p></div><div class="heading-actions"><button class="quiet-button" data-action="metadata">Run details ⓘ</button><button class="quiet-button" data-action="export">Export report ↓</button><a class="button secondary" href="'+route('garden',run.id,state.turn,state.dimension)+'">View in garden '+icon.leaf+'</a></div></section>'+contextMarkup()+'<section class="diagnostic-workspace"><div class="turn-rail" aria-label="Conversation turns">'+run.turns.map((_,i)=>{const rr=result(state.dimension,i);return '<button data-turn="'+(i+1)+'" class="turn-tab '+rr.status+(i===state.turn-1?' active':'')+'" aria-label="Turn '+(i+1)+', '+STATUS[rr.status].label+'" '+(i===state.turn-1?'aria-current="step"':'')+'><span>'+String(i+1).padStart(2,'0')+'</span><i></i></button>'}).join('')+'</div><div class="conversation-column"><div class="conversation-top"><span class="eyebrow">TURN '+state.turn+' OF '+run.turns.length+'</span><div><button class="icon-button" data-action="prev" aria-label="Previous turn" '+(state.turn===1?'disabled':'')+'>‹</button><button class="icon-button" data-action="next" aria-label="Next turn" '+(state.turn===run.turns.length?'disabled':'')+'>›</button></div></div><article class="user-message"><span class="speaker-label">USER</span><p>'+esc(t.user)+'</p></article><article class="assistant-message"><span class="speaker-label">'+esc(run.kind==='authored'?'AUTHORED ASSISTANT':run.model_label.toUpperCase())+' <span>· Original response</span></span><div class="formatted-response">'+renderText(t.assistant)+'</div></article></div><aside class="diagnosis-column"><label class="field-label" for="dimension-select">Evaluation dimension</label><select id="dimension-select" aria-label="Evaluation dimension">'+DIMENSIONS.map(d=>'<option value="'+d.id+'" '+(d.id===state.dimension?'selected':'')+'>'+d.id+' · '+d.name+'</option>').join('')+'</select><div class="diagnosis-status">'+badge(r)+'<p>'+esc(r.source)+'</p></div><div class="criterion-box"><span class="eyebrow">APPLICABLE CRITERION</span><p>'+esc(criterion())+'</p><button class="text-link" data-action="rubric">View original rubric ↗</button></div>'+evidenceLinks(run,state.turn)+'<details class="assessment-disclosure"><summary>Assessment records &amp; review</summary>'+assessmentRecords()+'<button class="text-link" data-action="review">Review this assessment ↗</button></details><div class="history-note">'+(past().hasPriorIssue?'An earlier issue remains in this trajectory. Current performance and past issues are separate.':'This judgment applies to the selected turn and criterion.')+'</div><p class="small-note">Reviews stay local and separate from imported records.</p></aside></section>';
}
function assessmentRecords(){
  const t=currentTurn(),canUse=state.dimension===run.dimension&&!override(),own=reviews[reviewKey()];
  let html='<div class="assessment-records"><h3>Assessment records</h3>';if(run.specification){for(const a of (t.evaluations||[]).filter(a=>a.dimension===state.dimension))html+='<div class="record configured-record"><div><strong>'+esc(a.criterion_id)+'</strong><span>'+esc(a.score??a.status)+' / 3</span></div><p>'+esc(a.explanation)+'</p><p class="small-note">'+esc(a.source)+' · '+esc(a.evaluator||'not executed')+'</p><p>'+esc(JSON.stringify(a.evidence))+'</p></div>';}
  if(!canUse)html+='<p class="small-note">No imported assessments apply to this criterion version.</p>';
  if(canUse&&run.kind==='authored')html+='<div class="record"><div><strong>Authored illustration</strong><span>'+t.authored_score+' / 3</span></div><p>'+esc(t.authored_explanation)+'</p></div>';
  if(canUse&&run.kind==='recorded'){
    for(let a of t.annotations||[])html+='<details class="record"><summary><strong>'+esc(a.name)+'</strong><span>'+a.score+' / 3</span></summary><div class="record-body"><p>'+esc(a.note||'No explanation supplied.')+'</p><small>Imported human score. Explanation provenance unconfirmed.</small></div></details>';
    if(!(t.annotations||[]).length)html+='<p class="small-note">No human annotations supplied for this turn.</p>';
    if(t.judge)html+='<details class="record llm-record"><summary><strong>LLM judge</strong><span>'+t.judge.score+' / 3</span></summary><div class="record-body"><small>'+esc(t.judge.model)+'</small><p>'+esc(t.judge.explanation)+'</p><small>Model-generated explanation. Verify against the conversation.</small></div></details>';
    if(t.unassigned_comment)html+='<details class="record"><summary>Imported comment</summary><div class="record-body"><p>'+esc(t.unassigned_comment)+'</p><small>Column was unlabeled; authorship unconfirmed.</small></div></details>';
  }
  if(own)html+='<details class="record" open><summary><strong>Your local review</strong><span>'+own.score+' / 3</span></summary><div class="record-body"><p>'+esc(own.note)+'</p><button class="text-link" data-action="remove-review">Remove local review</button></div></details>';
  if(result().disagreement)html+='<p class="difference-note">Judgments differ. Scores have not been averaged.</p>';
  return html+'</div>';
}
function openDialog(title,body,eyebrow='DETAILS'){stop();$('#dialog-eyebrow').textContent=eyebrow;$('#dialog-content').innerHTML='<h2 id="dialog-title">'+esc(title)+'</h2>'+body;if(!$('#dialog').open)$('#dialog').showModal();}
function metadata(){const fields=[['Case',scenario().name+' · '+run.id],['Data type',run.data_type||(run.kind==='authored'?'Author-constructed illustration':'Recorded model conversation')]];if(run.kind!=='authored'&&!run.fixture)fields.push(['Model family',run.family||'Custom application'],['Version',run.model_id||'Not recorded']);openDialog('Run details','<dl class="metadata-list">'+fields.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>','CASE & TARGET');}

function customize(){openDialog('Your standards, made explicit.','<p class="dialog-intro">An edited criterion gets a new version. Imported scores remain attached to the original rubric.</p><form id="criterion-form"><label class="field-label" for="criterion-dim">Dimension</label><select id="criterion-dim" name="dimension">'+DIMENSIONS.map(d=>'<option value="'+d.id+'" '+(d.id===state.dimension?'selected':'')+'>'+d.id+' · '+d.name+'</option>').join('')+'</select><label class="field-label" for="criterion-text">Observable criterion</label><textarea id="criterion-text" name="text" rows="5" maxlength="1200" required>'+esc(override()?.text||(state.dimension===run.dimension?originalCriterion():''))+'</textarea><p class="small-note">New criteria stay unassessed until you add an applicable review. No automatic grader is connected.</p><div class="form-actions"><button class="button primary" type="submit">Save criterion</button><button class="quiet-button" type="button" data-action="reset-criterion">Restore original</button></div></form>','CUSTOMIZE · '+scenario().name);}
function review(){const old=reviews[reviewKey()];openDialog('Add your review','<p class="dialog-intro">'+esc(dimName())+' · Turn '+state.turn+'. Your assessment stays separate from the supplied annotations.</p><div class="criterion-box"><p>'+esc(criterion())+'</p></div><form id="review-form"><label class="field-label" for="review-score">Your score</label><select id="review-score" name="score" required><option value="">Choose a score</option>'+[[1,'Does not meet'],[2,'Partly meets'],[3,'Meets']].map(([v,l])=>'<option value="'+v+'" '+(old?.score===v?'selected':'')+'>'+v+' · '+l+' criterion</option>').join('')+'</select><label class="field-label" for="review-note">Reason and supporting turn evidence</label><textarea id="review-note" name="note" rows="4" maxlength="3000" required>'+esc(old?.note||'')+'</textarea><button class="button primary" type="submit">Save local review</button></form><p class="small-note">Saved in this browser. Export the case to keep a portable copy.</p>','LOCAL REVIEW');}
function download(name,obj){let url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportResults(){download('deeproject-'+run.id.replace(/[^\w-]/g,'')+'-results.json',{...run,export_metadata:{schema_version:2,mode:run.specification?'configured-evaluation':'recorded-log-review',exported_at:new Date().toISOString(),default_display_rule:run.specification?'configured-assessments; source-records-retained':'adjudication-if-present; human-agreement; disagreement-pending; llm-provisional',selected_turn:state.turn,selected_dimension:state.dimension},local_criteria:Object.fromEntries(Object.entries(criteria).filter(([k])=>k.startsWith(run.scenario+':'))),local_reviews:Object.fromEntries(Object.entries(reviews).filter(([k])=>k.startsWith(run.id+':')))});toast('Case and review records exported.');}
function exportCase(){openDialog('Export results','<p class="dialog-intro">A readable report and a complete data record serve different tasks. Specifications are exported from Design.</p><div class="report-preview">'+renderText(markdownReport(run).split('## Original conversation')[0])+'</div><div class="export-options"><button class="button primary" data-action="export-report">Download findings · Text ↓</button><button class="button secondary" data-action="export-data">Download results · JSON ↓</button></div>','REPORT & DATA');}
function addLocalRun(data){validateRun(data);if(data.specification){const errs=validateSpecification(data.specification);if(errs.length)throw Error(errs.join(' '));}if(index.runs.some(r=>r.id===data.id)){data.source_run_id=data.id;data.id='IMPORT-'+Date.now();}if(!index.scenarios.some(s=>s.id===data.scenario))index.scenarios.push({id:data.scenario,name:data.record_type==='agent_events'?'Agent behavior protocol':data.fixture?'Project handover fixture':'Local executions',description:data.fixture?'Author-defined synthetic execution; no model called.':'Results produced or imported locally.',goal:'Check configured requirements against original messages.',constraints:[],eyebrow:'LOCAL EXECUTION'});cache.set(data.id,data);index.runs.push({id:data.id,scenario:data.scenario,kind:data.kind,dimension:data.dimension,record_type:data.record_type,configured:!!data.specification,issue_count:data.issues?.length,first_issue_turn:data.issues?.[0]?.first_observed,family:data.family,model_label:data.model_label,model_id:data.model_id,turn_count:data.events?.length||data.turns.length,human_count:data.turns?.filter(t=>t.annotations?.length).length||0});imported.push(data);storage.write('deeproject-v2-imports',imported);return data;}

async function loadRun(id){if(cache.has(id))return cache.get(id);const entry=index.runs.find(r=>r.id===id);if(!entry)throw Error('This case is not available. Open the case library to choose another.');const response=await fetch(entry.path);if(!response.ok)throw Error('The case could not be loaded. Please retry.');const data=validateRun(await response.json());if(data.id!==id)throw Error('Case identity mismatch.');cache.set(id,data);return data;}
async function render(){
  closeNavigation();const fromHome=state.page==='home';const token=++renderToken;stop();eventViewer?.dispose();scene?.dispose();scene=null;state=parseRoute(location.hash);document.body.dataset.page=state.page;inspecting=false;syncNav();
  if(state.page==='home'){state.run='R06';state.turn=1;state.dimension='A';}
  $('#main').innerHTML='<div class="loading-state" role="status">Loading conversation…</div>';
  try{const loaded=await loadRun(state.run);if(token!==renderToken)return;run=loaded;state.turn=Math.min(state.turn,run.events?.length||run.turns.length);if(run.record_type!=='agent_events'&&!DIMENSIONS.some(d=>d.id===state.dimension))state.dimension=run.dimension||'A';document.body.dataset.page=state.page;syncNav();$('#footer-mode').textContent=['design','run','docs'].includes(state.page)?'Design → execute → inspect · local-first':run.fixture?'Synthetic fixture · no model called':run.kind==='authored'?'Authored example · no model run':'Recorded evidence · sources kept separate';
    if(state.page==='design')studio.design();if(state.page==='run')studio.run();if(state.page==='compare')await studio.compare();if(state.page==='docs')renderAgentDocs($('#main'));if(state.page==='home')renderHome();if(state.page==='garden'){if(run.record_type==='agent_events')eventViewer.render(run,state.turn,state.dimension);else renderGarden(fromHome);}if(state.page==='workbench')renderWorkbench();if(state.page==='diagnostics'){if(run.record_type==='agent_events')eventViewer.render(run,state.turn,state.dimension);else renderDiagnostic();}
    document.title=({home:'Deeproject · AI Garden',design:'Evaluation Design',run:'Run evaluation',workbench:'Results',compare:'Compare runs',docs:'Local harness'}[state.page]||scenario().name)+' — Deeproject';window.scrollTo({top:0,behavior:'instant'});
  }catch(e){if(token===renderToken)$('#main').innerHTML='<section class="error-state"><span class="eyebrow">CASE UNAVAILABLE</span><h1>We couldn’t open this conversation.</h1><p>'+esc(e.message)+'</p><button class="button primary" data-action="retry">Try again</button><a class="text-link" href="#workbench?run=R06&turn=1&dim=A">Open case library ↗</a></section>';}
}

document.addEventListener('click',e=>{
  if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return;}
  const action=e.target.closest('[data-action]')?.dataset.action,dim=e.target.closest('[data-dim]')?.dataset.dim,turn=e.target.closest('[data-turn]')?.dataset.turn,filter=e.target.closest('[data-filter]')?.dataset.filter;
  if(dim){selectDimension(dim);return}if(turn){stop();setTurn(Number(turn));return}if(filter){const entry=index.runs.find(r=>r.scenario===filter);location.hash=route('workbench',entry.id,1,'A');return}
  if(e.target.closest('#play')){togglePlay();return}if(!action)return;
  if(action==='skip-entry'){scene?.skipEntry();finishGardenEntry();}if(action==='export-report'){const local=Object.fromEntries(Object.entries(reviews).filter(([k])=>k.startsWith(run.id+':')));saveFile('deeproject-'+run.id.replace(/[^\w-]/g,'')+'-report.txt',markdownReport(run)+'\n\n## Separate local reviews\n'+JSON.stringify(local,null,2));$('#dialog').close();}if(action==='export-data'){exportResults();$('#dialog').close();}if(action==='metadata')metadata();if(action==='customize')customize();if(action==='review')review();if(action==='export')exportCase();if(action==='retry')render();
  if(action==='prev'||action==='next'||action==='restart'){stop();setTurn(action==='restart'?1:state.turn+(action==='next'?1:-1));}
  if(action==='close-evidence'){inspecting=false;paintGarden();scene?.overview();$('[data-dim="'+state.dimension+'"]').focus();}
  if(action==='overview'){scene?.overview();inspecting=false;if(state.page==='garden')paintGarden();}
  if(action==='rotate-left')scene?.rotate(-.32);if(action==='rotate-right')scene?.rotate(.32);if(action==='zoom-in')scene?.zoom(-2);if(action==='zoom-out')scene?.zoom(2);
  if(action==='assessments')openDialog('Assessments · Turn '+state.turn,'<p class="dialog-intro">'+esc(criterion())+'</p>'+assessmentRecords(),'JUDGMENT SOURCES');
  if(action==='rubric')openDialog('Original rubric','<div class="rubric-text">'+renderText(run.rubric)+'</div>','SOURCE STANDARD · '+run.rubric_version);
  if(action==='import')$('#import-file').click();
  if(action==='reset-criterion'){const dim=$('#criterion-dim')?.value||state.dimension;delete criteria[criterionKey(dim)];storage.write('deeproject-v2-criteria',criteria);$('#dialog').close();if(state.page==='garden')paintGarden();else renderDiagnostic();toast('Original criterion restored. Imported assessments are available again.');}
  if(action==='remove-review'){delete reviews[reviewKey()];storage.write('deeproject-v2-reviews',reviews);if($('#dialog').open)$('#dialog').close();if(state.page==='garden')paintGarden();else renderDiagnostic();toast('Local review removed; imported records unchanged.');}
});
document.addEventListener('input',e=>{if(e.target.id==='timeline'){stop();setTurn(Number(e.target.value))}});
document.addEventListener('change',e=>{
  if(e.target.id==='scenario-select'){stop();const entry=index.runs.find(r=>r.scenario===e.target.value&&r.family===run.family)||index.runs.find(r=>r.scenario===e.target.value);location.hash=route(state.page,entry.id,1,'A');}
  if(e.target.id==='model-select'){stop();location.hash=route(state.page,e.target.value,Math.min(state.turn,index.runs.find(r=>r.id===e.target.value).turn_count),state.dimension);}
  if(e.target.id==='dimension-select'){state.dimension=e.target.value;syncUrl();renderDiagnostic();}
  if(e.target.id==='criterion-dim'){$('#criterion-text').value=override(e.target.value)?.text||(e.target.value===run.dimension?originalCriterion():'');}
});
document.addEventListener('submit',e=>{
  if(e.target.id==='criterion-form'){e.preventDefault();const fd=new FormData(e.target),dim=fd.get('dimension'),text=String(fd.get('text')).trim();if(!text)return;criteria[criterionKey(dim)]={text,version:'local-'+Date.now(),created_at:new Date().toISOString()};storage.write('deeproject-v2-criteria',criteria);state.dimension=dim;syncUrl();$('#dialog').close();if(state.page==='garden')paintGarden();else renderDiagnostic();toast('Criterion saved. Previous scores do not apply to this version.');}
  if(e.target.id==='review-form'){e.preventDefault();const fd=new FormData(e.target),score=Number(fd.get('score')),note=String(fd.get('note')).trim();if(![1,2,3].includes(score)||!note)return;reviews[reviewKey()]={score,note,source:'local-user-review',criterion_version:override()?.version||run.rubric_version,created_at:new Date().toISOString()};storage.write('deeproject-v2-reviews',reviews);$('#dialog').close();if(state.page==='garden')paintGarden();else renderDiagnostic();toast('Local review saved. Original assessments retained.');}
});
$('#close-dialog').onclick=()=>$('#dialog').close();
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function openAbout(){closeNavigation();openDialog('Define expectations. Inspect behavior.','<p class="dialog-intro">Deeproject connects customizable behavioral specifications to event-based checks, multi-turn evaluation and evidence inspection.</p><div class="about-copy"><h3>Human expertise upstream</h3><p>Define observable criteria, evidence and rating anchors. The harness applies configured checks; reviewers examine uncertainty and refine standards.</p><h3>What is implemented</h3><p>Event rules for goals, permission, tool outcomes, recorded state, verification and completion; custom dimensions; local Python evaluators; legacy conversation checks; reports and comparison. Event fixtures are author-constructed. No calibrated semantic judge or participant validation is bundled.</p><h3>Recorded evidence</h3><p>Nine recorded conversations across three domains and three models. Imported ratings cover A only. Human and LLM records are separate; agreement is not proof of correctness.</p><h3>Research scope</h3><p>This prototype does not guarantee safety. Developer usability and diagnostic accuracy require further empirical validation.</p><h3>Future directions</h3><p>Future explorations may introduce animal characters to represent interacting AI agents or stakeholder perspectives.</p></div><a class="text-link" href="#docs">Install the harness →</a>','ABOUT DEEPROJECT');}
document.querySelectorAll('[data-about]').forEach(button=>button.addEventListener('click',openAbout));

$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('Choose a JSON result smaller than 5 MB.');let data=JSON.parse(await file.text());if(data.criteria&&data.context){studio.importSpec(data);return;}data=addLocalRun(data.run||data);location.hash=route('diagnostics',data.id,1,data.dimension);toast('Results imported locally. Original sources retained.');}catch(err){toast('Import failed: '+err.message)}finally{e.target.value=''}};

document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
window.addEventListener('hashchange',render);
try{const response=await fetch('data/index.json');if(!response.ok)throw Error('Case directory unavailable');index=await response.json();document.body.dataset.runtime=index.runtime?.mode||'hosted';for(const data of imported){try{validateRun(data);cache.set(data.id,data);if(!index.scenarios.some(s=>s.id===data.scenario))index.scenarios.push({id:data.scenario,name:data.fixture?'Project handover fixture':data.specification?.context?.domain||'Imported cases',description:data.fixture?'Author-defined synthetic execution; no model called.':'Locally imported conversations.',goal:'Review the provided criterion.',constraints:[],eyebrow:'LOCAL IMPORT'});index.runs.push({id:data.id,scenario:data.scenario,kind:data.kind,dimension:data.dimension,record_type:data.record_type,configured:!!data.specification,issue_count:data.issues?.length,first_issue_turn:data.issues?.[0]?.first_observed,family:data.family,model_label:data.model_label||'Imported model',model_id:data.model_id,turn_count:data.events?.length||data.turns.length,human_count:data.turns?.filter(t=>t.annotations?.length).length||0})}catch{}}const studioApi={index,getRun:loadRun,addRun:addLocalRun,route,toast};studio=createAgentStudio(studioApi,createStudio(studioApi));eventViewer=createEventViewer({route,tabs:studio.tabs,page:()=>state.page,dialog:openDialog});await render();}catch(e){$('#main').innerHTML='<div class="error-state"><h1>The case directory could not be loaded.</h1><p>'+esc(e.message)+'</p><button class="button primary" data-action="retry-directory">Reload page</button></div>';document.addEventListener('click',e=>{if(e.target.closest('[data-action="retry-directory"]'))location.reload()})}
